    )

    $result = Invoke-TkProcess -FilePath 'DISM.exe' `
                               -ArgumentList @('/Online', '/Cleanup-Image', '/RestoreHealth') `
                               -TimeoutSeconds 5400

    return ($result.ExitCode -eq 0)
}

