function Reset-TkIconCache {
    [CmdletBinding(SupportsShouldProcess)]
    [OutputType([bool])]
    param()

    if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Rebuild the icon cache')) {
        return $false
    }

    $cachePath = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'

