# Hardening
# ---------------------------------------------------------------------------

<#
.SYNOPSIS
    Runs the hardening check and renders it grouped by area.
#>
function Show-TkHardeningCheck {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Checking the hardening controls...' `
        -ScriptBlock { Invoke-TkHardeningCheck } `
        -OnComplete {
            param($result)

            $findings = @($result.Output)
            Set-TkLastDiagnostic -Name 'hardening' -Data $findings

            $document = New-TkFlowDocument

            Add-TkHeading -Document $document -Text 'Hardening' -Level 1

            $failing = @($findings | Where-Object { $_.Severity -eq 'Fail' }).Count
            $warning = @($findings | Where-Object { $_.Severity -eq 'Warning' }).Count

            Add-TkParagraph -Document $document -Muted -Text (
                '{0} controls checked: {1} failing, {2} worth attention. These decide whether an intrusion stays on one machine or reaches the whole estate.' -f
                    $findings.Count, $failing, $warning
            )

            foreach ($area in (@($findings | ForEach-Object { $_.Area }) | Select-Object -Unique)) {

                Add-TkHeading -Document $document -Text $area -Level 2

                foreach ($finding in ($findings | Where-Object { $_.Area -eq $area })) {

                    $note = $finding.Why

                    if ($finding.Fix) {
                        $note += '  What to change: ' + $finding.Fix
                    }

                    Add-TkSeverityLine -Document $document -Severity $finding.Severity `
                        -Heading $finding.Name -Detail $finding.State -Note $note
                }
            }

            Set-TkDocument -ControlName 'HardeningOutput' -Document $document
            Set-TkStatus -Text ('Hardening: {0} failing, {1} warnings.' -f $failing, $warning)
        }
}

<#
.SYNOPSIS
    Writes the last rendered report to a JSON file.

.PARAMETER ControlName
    Only used to keep the two export buttons distinguishable in the log.
#>
function Export-TkDiagnosticReport {
    [CmdletBinding()]
    param(
        [Parameter()]
        [string] $ControlName = ''
    )

    if (-not $script:TkLastDiagnostic) {
        Set-TkStatus -Text 'Run a check first.'
        return
    }

    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title    = 'Export the report'
    $dialog.Filter   = 'JSON report (*.json)|*.json'
    $dialog.FileName = '{0}-{1}-{2}.json' -f $env:COMPUTERNAME, $script:TkLastDiagnosticName, (Get-Date -Format 'yyyyMMdd')

    if (-not $dialog.ShowDialog()) {
        return
    }

    try {
        [pscustomobject]@{
            Computer    = $env:COMPUTERNAME
            Report      = $script:TkLastDiagnosticName
            GeneratedAt = (Get-Date).ToString('s')
            Toolkit     = (Get-TkContext).Version
            Data        = $script:TkLastDiagnostic
        } | ConvertTo-Json -Depth 6 |
            Set-Content -LiteralPath $dialog.FileName -Encoding UTF8 -ErrorAction Stop

        Set-TkStatus -Text ('Report written to {0}' -f $dialog.FileName)
    }
    catch {
        Write-TkLog -Level Error -Category 'Diagnostics' -Message (
            'The report could not be written: {0}' -f $_.Exception.Message
        )
    }
}


# ==========================================================================
# Source: src/Start-Toolkit.ps1
# ==========================================================================

<#
    Toolkit - Entry point

    Start-up sequence:

      1. Build the shared context and start logging.
      2. Validate the host.
      3. Check the thread apartment, because WPF needs STA.
      4. Load the data catalogs.
      5. Build the window, wire the pages and run the message loop.

    Nothing here touches the system. The toolkit is safe to start on any
    machine; only an explicit click changes anything.
#>

<#
.SYNOPSIS
    Starts the toolkit.

.DESCRIPTION
    The single public entry point. Called by the development launcher, by the
    compiled single file build, and by the tests.

.PARAMETER SourceUri
    HTTPS location this instance was launched from. Recorded so an elevation
    restart can replay the same source when there is no script file on disk.

.PARAMETER NoGui
    Loads everything and returns without showing a window. Used by the tests
    and by anyone wanting the functions in a plain console session.

.EXAMPLE
    Start-Toolkit

.EXAMPLE
    Start-Toolkit -NoGui
#>
function Start-Toolkit {
    [CmdletBinding()]
    param(
        [Parameter()]
        [string] $SourceUri,

        [Parameter()]
        [switch] $NoGui
    )

    # --- 1. Context and logging ------------------------------------------
    $ctx = Initialize-TkContext
    Import-TkSettings | Out-Null

    # Recorded so the elevation restart can replay the same source when the
    # toolkit was piped in and there is no script file on disk to re-run.
    if ($SourceUri) {
        $ctx.SourceUri = $SourceUri
    }

    Write-TkLog -Level Information -Category 'Startup' -Message (
        '{0} {1} ({2}) starting.' -f $ctx.AppName, $ctx.Version, $ctx.Commit
    )

    # --- 2. Host validation ----------------------------------------------
    if (-not (Initialize-TkEnvironment)) {

        Write-TkLog -Level Error -Category 'Startup' -Message 'The host does not meet the requirements. Stopping.'
        return
    }

    # --- 3. Data ----------------------------------------------------------
    Import-TkAllCatalogs

    if ($NoGui) {

        Write-TkLog -Level Information -Category 'Startup' -Message (
            'Loaded without a window. Every Tk function is available in this session.'
        )

        return $ctx
    }

    # --- 4. Apartment state ----------------------------------------------
    # WPF requires STA. A console started with -MTA can load the assemblies
    # but faults when the window is shown, so this is caught here with an
    # actionable message rather than as a crash later.
    if (-not (Test-TkIsStaThread)) {

        Write-TkLog -Level Error -Category 'Startup' -Message (
            'This session is not single threaded (MTA). Restart with: powershell -STA -File <script>'
        )

        return
    }

    if (-not (Import-TkUiAssembly)) {
        return
    }

    # --- 5. Interface -----------------------------------------------------
    try {
        $window = New-TkMainWindow

        Initialize-TkShell
        Initialize-TkRunspacePool
        Start-TkTaskPump

        Initialize-TkSystemPage
        Initialize-TkSoftwarePage
        Initialize-TkTweaksPage
        Initialize-TkFixesPage
        Initialize-TkNetworkPage
        Initialize-TkNetworkAdminPage
        Initialize-TkSecurityPage
        Initialize-TkThreatHuntingPage
        Initialize-TkDiagnosticsPage

        Show-TkPage -Name 'System'
        Update-TkSystemPage

        if (-not $ctx.IsElevated) {

            Write-TkLog -Level Warning -Category 'Startup' -Message (
                'Running as a standard user. Inventory, network and security tools work; anything that changes the system is disabled until you restart elevated.'
            )
        }

        Set-TkStatus -Text 'Ready.'

        Write-TkLog -Level Information -Category 'Startup' -Message 'Interface ready.'

        # Blocks until the window closes.
        $window.ShowDialog() | Out-Null
    }
    catch {
        Write-TkLog -Level Error -Category 'Startup' -Message (
            'The interface failed to start: {0}' -f $_.Exception.Message
        )

        Write-TkLog -Level Debug -Category 'Startup' -Message $_.ScriptStackTrace

        throw
    }
    finally {
        Stop-TkThreading
    }
}


# ==========================================================================
# Embedded resources
# ==========================================================================

# Build metadata, overriding the development defaults declared in Config.ps1.
$script:TkAppVersion = '1.0.0'
$script:TkAppCommit  = '9b03267'

# Interface markup, base64 encoded so no quoting can collide with the XAML.
$script:TkEmbeddedXaml = [System.Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

# Data catalogs, keyed by name and decoded on first use.
$script:TkEmbeddedCatalogsRaw = @{
    'applications' = ''
    'fixes' = ''
    'network-knowledge' = ''
    'tweaks' = ''
    'vendor-commands' = ''
    'vendor-support' = ''
}

$script:TkEmbeddedCatalogs = @{}

foreach ($catalogName in $script:TkEmbeddedCatalogsRaw.Keys) {

    $script:TkEmbeddedCatalogs[$catalogName] = [System.Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($script:TkEmbeddedCatalogsRaw[$catalogName])
    )
}

# ==========================================================================
# Entry point
# ==========================================================================

# The file the operator ran, used by an elevation restart. Empty when this
# script was piped straight into the shell, in which case the source URL is
# replayed instead.
$script:TkEntryScript = $PSCommandPath

if ($NoGui) {
    Start-Toolkit -NoGui -SourceUri $SourceUri
}
else {
    Start-Toolkit -SourceUri $SourceUri
}
